// AnalyzeRequest Analyze a bundle into an import preview.
//
// Provide exactly one of “source“ (pasted text), “source_url“ (a URL the
// server fetches behind the SSRF guard), “files“ (an agent folder) or
// “bundle“ (a canonical bundle, e.g. one edited after an earlier analyze).
// “source_url“ is what a landing-page deep-link (`/bundles/import?src=<url>`)
// uses for one-click installs; “files“ is what “agentarea deploy“ sends.
type AnalyzeRequest struct {
	// Bundle A canonical bundle, as an earlier analyze returned it.
	Bundle *BundleInput `json:"bundle"`

	// Files A bundle folder: relative POSIX path -> UTF-8 file text, rooted at agentarea.yaml (or the deprecated agent.yaml). 5MB total.
	Files *map[string]string `json:"files"`

	// Into The install to update: its id, or the name of exactly one install. Without it the bundle's name must be free in the workspace, else the plan blocks with code bundle_exists.
	Into *string `json:"into"`

	// Origin Where the folder came from; informational.
	Origin *BundleOrigin `json:"origin"`

	// SetupValues Setup values the install will be given, so a redeploy plan shows what a changed value updates. The plan_digest holds only for these values.
	SetupValues *map[string]interface{} `json:"setup_values,omitempty"`

	// Source Raw bundle source text (YAML or JSON).
	Source *string `json:"source"`

	// SourceUrl URL to fetch raw bundle source from (YAML or JSON).
	SourceUrl *string `json:"source_url"`
}

// BundleInput The canonical, fully-inlined package object.
type BundleInput struct {
	Agents      *[]BundleAgent      `json:"agents,omitempty"`
	Automations *[]BundleAutomation `json:"automations,omitempty"`
	Channels    *[]BundleChannel    `json:"channels,omitempty"`
	Description *string             `json:"description,omitempty"`
	DisplayName *string             `json:"display_name"`
	Mcps        *[]BundleMcp        `json:"mcps,omitempty"`

	// Metadata Marketplace presentation metadata (parity with plugin/app listings).
	Metadata *BundleMetadata `json:"metadata,omitempty"`

	// Name Stable package identifier (idempotency key).
	Name          string               `json:"name"`
	Openapi       *[]BundleOpenAPI     `json:"openapi,omitempty"`
	Policies      *[]BundlePolicyInput `json:"policies,omitempty"`
	Projects      *[]BundleProject     `json:"projects,omitempty"`
	SchemaVersion *string              `json:"schema_version,omitempty"`
	Setup         *[]SetupField        `json:"setup,omitempty"`
	Skills        *[]BundleSkill       `json:"skills,omitempty"`
	Streams       *[]BundleStream      `json:"streams,omitempty"`
	Tasks         *[]BundleTask        `json:"tasks,omitempty"`
}

